package got.client.gui;
import got.network.C2SCreateCustomWaypointPacket;import got.network.GOTNetwork;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.components.EditBox;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;
public final class GOTGuiCreateWaypoint extends Screen { private final Screen parent; private EditBox name; public GOTGuiCreateWaypoint(Screen parent){super(Component.translatable("got.fastTravel.custom.create"));this.parent=parent;} @Override protected void init(){int cx=width/2,cy=height/2;name=new EditBox(font,cx-100,cy-12,200,20,title);name.setMaxLength(32);name.setValue("Waypoint");addRenderableWidget(name);addRenderableWidget(Button.builder(Component.translatable("got.fastTravel.custom.create"),b->{GOTNetwork.CHANNEL.sendToServer(new C2SCreateCustomWaypointPacket(name.getValue()));onClose();}).bounds(cx-100,cy+16,96,20).build());addRenderableWidget(Button.builder(Component.translatable("gui.cancel"),b->onClose()).bounds(cx+4,cy+16,96,20).build());} @Override public void render(GuiGraphics g,int x,int y,float p){renderBackground(g);g.drawCenteredString(font,title,width/2,height/2-38,0xFFFFFF);super.render(g,x,y,p);} @Override public void onClose(){if(minecraft!=null)minecraft.setScreen(parent);} public boolean isPauseScreen(){return false;} }
